    internal Settings Build(Resource document,Resource source,Settings layout,Settings graph,Func<bool> cancelled)
    {
        var settings=new Settings();Settings Result(string[] errors)=>new() {["settings"]=settings,["errors"]=errors,["warnings"]=Array.Empty<string>()};var forests=source.Get("forests").AsGodotArray();if(forests.Count==0)return Result(Array.Empty<string>());var field=source.Get("terrain_field").As<RefCounted>();if(field==null)return Result(new[]{"Choose a terrain before generating forests."});var masks=development(source,layout,graph,field.Get("to_ground").AsTransform3D(),false);var components=document.Get("components").AsGodotArray();string owner=source.Get("world_id").AsString();
